---@class MINIGameView : ViewBase
MINIGameView = class("MINIGameView", ViewBase)

function MINIGameView:initialize()
    ViewBase.initialize(self)
    ViewBase.RegisteAction(self, "MINIGameViewAction")
end

function MINIGameView:Awake()
    self:LoadCarShell()
    self:SetUICamera()
    self.BackBtn=  CommonHelper:HButtonSetCallback("BackButton", self.gameObject, function(data)
        if MINIGameManager:Get().gameAwardUnclaimed then
            local boxFunc = function()
                local str = CommonHelper:GetTempStr_Default(TemplateStringID.MINIGameAwardTip)
                local ret = MessageBoxHelp:Get():OpenBox_OKCancel(UIColor.Orange, str)
                if ret == MessageBoxHelp.BtnType.OK then
                    SceneManager:Get():LoadingMainCity()
                    CommonHelper:SetHButtonClick(self.BackBtn,false,true)
                end
            end
            MessageBoxHelp.Get():StartCoroutineBox(boxFunc)
        else
            SceneManager:Get():LoadingMainCity()
            CommonHelper:SetHButtonClick(self.BackBtn,false,true)
        end
    end)

    local GameOverListener = function()
        if MINIGameManager:Get().gameAwardUnclaimed then
            MINIGameSubsystem:Get():SendMsg_MINIGameAward()
        end
    end
    CSMINIGameManager:AddGameOverListener(GameOverListener)

    self.StartUp= CommonHelper:HButtonSetCallback("StartUpButton", self.gameObject, function(data)
        HQualitySetting:SetIsFramerateAuto(false)
        CSMINIGameManager:SetTimeScale(3)
        CSMINIGameManager:StartUp()
        CommonHelper:SetHButtonClick(self.StartUp,false,true)
    end)
end

function MINIGameView:LoadCarShell()
    self.AllAsset={}
    local assetBody = AssetsManager.LoadAsync("minigamecar.prefab", typeof(GameObject))
    table.insert(self.AllAsset,assetBody)
    ---@type table<number,minigame_config_cell>
    local cfg= ClientDataManager:Get():GetDataTable(ConfigNames.minigame_config):GetConfigData()
    local randomTable = self:Random(4,1,#cfg)
    local shellIDTable={}
    local robotNames={}
    for i = 1, #randomTable do
        table.insert(shellIDTable,cfg[randomTable[i]].cellid)
        table.insert(robotNames,CommonHelper:GetTempStr_Default(cfg[randomTable[i]].name))
    end
    robotNames[1]=PlayerDataManager:Get():GetPlayerName()
    CSMINIGameManager:SetAiCarNames(robotNames[1],robotNames[2],robotNames[3],robotNames[4])
    assetBody:AddComplete(function(asset)
        for i = 1, #shellIDTable do
            local resultBody = CommonHelper:InstantiateGameObjectByObject(asset.asset)
            self: BuildCarShell(shellIDTable[i], function(shellObj)
                CSMINIGameManager:SetBodyShell(i-1,resultBody,shellObj)
            end)
        end
    end)

end
---@param count number 指定要生成的不同随机数的数量 随机数的最大值
---@param rangeMin number 随机数的最小值
---@param rangeMax number 随机数的最大值
function MINIGameView:Random(count,rangeMin,rangeMax)

    if rangeMax-rangeMin<count then
        logError('Random illegal')
        return
    end
    local generatedNumbers = {} -- 用于存储生成的不同随机数的 Lua table

    while #generatedNumbers < count do
        local randomNumber = math.random(rangeMin, rangeMax) -- 生成指定范围内的随机数
        local isNumberGenerated = false
        for i = 1, #generatedNumbers do -- 检查该随机数是否已经生成过
            if generatedNumbers[i] == randomNumber then
                isNumberGenerated = true
                break
            end
        end
        if not isNumberGenerated then -- 如果该随机数尚未生成过，则加入 Lua table 中
            table.insert(generatedNumbers, randomNumber)
        end
    end
    return generatedNumbers
end
function MINIGameView:BuildCarShell(id,func)
    local carShellCfg=CarBuilder:GetCarShellCfg(id)
    local meshCfg= CarBuilder:GetPartMeshCfg(id,1)
    local assetInfo  = AssetsManager.LoadAsync(meshCfg.mesh, typeof(GameObject))
    table.insert(self.AllAsset,assetInfo)
    assetInfo:AddComplete(function(asset)
        local stickerid=carShellCfg.defaultSticker
        local IsColor = carShellCfg.isColour
        local colorid=0
        local CarShellObj = CommonHelper:InstantiateGameObjectByObject(asset.asset)
        self:BuildSticker(CarShellObj,stickerid)
        self:BuildShellColor(CarShellObj,colorid,IsColor)
        if func then
            func(CarShellObj)
        end
    end)
end

function MINIGameView:BuildSticker(obj,stickerid)
    ---@type apsticker_config_cell
    local stickercfg = CommonHelper:GetTableDataByID(ConfigNames.apsticker_config, stickerid)
    if stickercfg ~= nil then
        local shell =obj
        if shell == nil then
            return
        end
        local m = UIUtil.GetGameobjectComponent(shell, typeof(MeshRenderer))
        local mat=  MatCacheDataMgr:Get():LoadMaterial(stickercfg.NewMat)
        if mat == nil   then
            local MatAsset = AssetsManager.LoadAsync(stickercfg.NewMat, typeof(Material))
            MatAsset:AddComplete(function(asset)
                table.insert(self.AllAsset,asset)
                mat = CommonHelper:InstantiateMaterialByObject(asset.asset)
                if mat then
                    if not CommonHelper:GameObjectIsNull(m) then
                        m.material = mat
                    end
                    for i = 1, ShellHoldCount do
                        m = UIUtil.GetTypeChildWightByParent("hole_0" .. i, shell, typeof(MeshRenderer))
                        if not CommonHelper:GameObjectIsNull(m) then
                            m.material = mat
                        end
                    end
                end
            end)

        else
            mat = CommonHelper:InstantiateMaterialByObject(mat)
            if mat then
                if not CommonHelper:GameObjectIsNull(m) then
                    m.material = mat
                end
                for i = 1, ShellHoldCount do
                    m = UIUtil.GetTypeChildWightByParent("hole_0" .. i, shell, typeof(MeshRenderer))
                    if not CommonHelper:GameObjectIsNull(m) then
                        m.material = mat
                    end
                end
            end
        end



    end
end
function MINIGameView:BuildShellColor(obj,colorid,iscolor)
    local shell = obj
    if shell == nil then
        return
    end
    local m = UIUtil.GetGameobjectComponent(shell, typeof(MeshRenderer))
    if  CommonHelper:GameObjectIsNull(m) then
        return
    end

    if colorid == 0 then
        if iscolor == 1 then
            CarBuilder:SetDefaultMatColorParam(m, true)
        else
            CarBuilder:SetDefaultMatColorParam(m, false)
        end
    else
        local colorcfg = CommonHelper:GetTableDataByID(ConfigNames.apcolor_config, colorid )
        if colorcfg then
            CarBuilder:SetMatColorParam(m, true, colorcfg.NewBaseColor, colorcfg.NewSSSColor, colorcfg.NewFakeColor, colorcfg.metallic, colorcfg.smoothness)
        end
    end

    for i = 1, ShellHoldCount do
        local render = UIUtil.GetTypeChildWightByParent("hole_0" .. i, shell, typeof(MeshRenderer))
        if not CommonHelper:GameObjectIsNull(render) then
            if colorid == 0 then
                if iscolor == 1 then
                    CarBuilder:SetDefaultMatColorParam(render, true)
                else
                    CarBuilder:SetDefaultMatColorParam(render, false)
                end
            else
                local colorcfg = self:GetColorResCfg(colorid)
                if colorcfg then
                    CarBuilder:SetMatColorParam(render, true, colorcfg.NewBaseColor, colorcfg.NewSSSColor, colorcfg.NewFakeColor, colorcfg.metallic, colorcfg.smoothness)
                end
            end
        end
    end

end

function MINIGameView:SetUICamera()
    for i = 0, CSMINIGameManager.RaceManager.CameraControllers.Length -1 do
        local baseCamera = UIUtil.GetTypeChildWightByParent("Camera",CSMINIGameManager.RaceManager.CameraControllers[i].gameObject,typeof(Camera))
        local cameraData = CSCameraExtensions.GetUniversalAdditionalCameraData(baseCamera)
        cameraData.renderType = CameraRenderType.Base
        local uiCamera =CSCameraManager.Get()._UICamera
        cameraData.cameraStack:Add(uiCamera)
    end
end

function MINIGameView:UnLoad()
    CSMINIGameManager:SetTimeScale(1)
    HQualitySetting:SetIsFramerateAuto(true)
    for i = 1, #self.AllAsset do
        AssetsManager.Unload(self.AllAsset[i])
        self.AllAsset[i]= nil
    end
    self.AllAsset=nil
end

function MINIGameView:OnClose()
   self:UnLoad()
end